003c/span\u003e(\u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003e\u0026lt;h3\u0026gt;❌ DB錯誤：\u003c/span\u003e\u0026quot;\u003c/span\u003e . \u003cspan class=pl-en\u003ehtmlspecialchars\u003c/span\u003e(\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ee\u003c/span\u003e-\u0026gt;\u003cspan class=pl-en\u003egetMessage\u003c/span\u003e()) . \u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003e\u0026lt;/h3\u0026gt;\u003c/span\u003e\u0026quot;\u003c/span\u003e);","}","","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_year\u003c/span\u003e = \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003e\u003cspan class=pl-c1\u003e_GET\u003c/span\u003e\u003c/span\u003e[\u003cspan class=pl-s\u003e\u0026#39;\u003cspan class=pl-s\u003eyear\u003c/span\u003e\u0026#39;\u003c/span\u003e] ?? \u003cspan class=pl-s\u003e\u0026#39;\u0026#39;\u003c/span\u003e;","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_keyword\u003c/span\u003e = \u003cspan class=pl-en\u003etrim\u003c/span\u003e(\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003e\u003cspan class=pl-c1\u003e_GET\u003c/span\u003e\u003c/span\u003e[\u003cspan class=pl-s\u003e\u0026#39;\u003cspan class=pl-s\u003ekeyword\u003c/span\u003e\u0026#39;\u003c/span\u003e] ?? \u003cspan class=pl-s\u003e\u0026#39;\u0026#39;\u003c/span\u003e);","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_group\u003c/span\u003e = \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003e\u003cspan class=pl-c1\u003e_GET\u003c/span\u003e\u003c/span\u003e[\u003cspan class=pl-s\u003e\u0026#39;\u003cspan class=pl-s\u003egroup\u003c/span\u003e\u0026#39;\u003c/span\u003e] ?? \u003cspan class=pl-s\u003e\u0026#39;\u0026#39;\u003c/span\u003e;","","\u003cspan class=pl-c\u003e// 年度清單\u003c/span\u003e","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003eyears\u003c/span\u003e = \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003epdo\u003c/span\u003e-\u0026gt;\u003cspan class=pl-en\u003equery\u003c/span\u003e(\u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003eSELECT DISTINCT team_year FROM teamdata ORDER BY team_year DESC\u003c/span\u003e\u0026quot;\u003c/span\u003e)-\u0026gt;\u003cspan class=pl-en\u003efetchAll\u003c/span\u003e(\u003cspan class=pl-c1\u003ePDO\u003c/span\u003e::\u003cspan class=pl-c1\u003eFETCH_COLUMN\u003c/span\u003e);","","\u003cspan class=pl-c\u003e// 類組清單\u003c/span\u003e","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003egroup_stmt\u003c/span\u003e = \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003epdo\u003c/span\u003e-\u0026gt;\u003cspan class=pl-en\u003eprepare\u003c/span\u003e(\u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003eSELECT group_ID, group_name FROM groupdata WHERE group_status = 1 ORDER BY group_ID ASC\u003c/span\u003e\u0026quot;\u003c/span\u003e);","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003egroup_stmt\u003c/span\u003e-\u0026gt;\u003cspan class=pl-en\u003eexecute\u003c/span\u003e();","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003egroups\u003c/span\u003e = \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003egroup_stmt\u003c/span\u003e-\u0026gt;\u003cspan class=pl-en\u003efetchAll\u003c/span\u003e();","","\u003cspan class=pl-c\u003e// 篩選條件\u003c/span\u003e","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ewhere\u003c/span\u003e = [\u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003elatest.projects_status = 3\u003c/span\u003e\u0026quot;\u003c/span\u003e];","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003eparams\u003c/span\u003e = [];","","\u003cspan class=pl-k\u003eif\u003c/span\u003e (\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_year\u003c/span\u003e) {","    \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ewhere\u003c/span\u003e[] = \u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003et.team_year LIKE ?\u003c/span\u003e\u0026quot;\u003c/span\u003e;","    \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003eparams\u003c/span\u003e[] = \u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003e%\u003c/span\u003e\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_year\u003c/span\u003e\u003cspan class=pl-s\u003e%\u003c/span\u003e\u0026quot;\u003c/span\u003e;","}","\u003cspan class=pl-k\u003eif\u003c/span\u003e (\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_keyword\u003c/span\u003e) {","    \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ewhere\u003c/span\u003e[] = \u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003e(t.team_project_name LIKE ? OR latest.projects_describe LIKE ?)\u003c/span\u003e\u0026quot;\u003c/span\u003e;","    \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003eparams\u003c/span\u003e[] = \u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003e%\u003c/span\u003e\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_keyword\u003c/span\u003e\u003cspan class=pl-s\u003e%\u003c/span\u003e\u0026quot;\u003c/span\u003e;","    \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003eparams\u003c/span\u003e[] = \u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003e%\u003c/span\u003e\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_keyword\u003c/span\u003e\u003cspan class=pl-s\u003e%\u003c/span\u003e\u0026quot;\u003c/span\u003e;","}","\u003cspan class=pl-k\u003eif\u003c/span\u003e (\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_group\u003c/span\u003e) {","    \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ewhere\u003c/span\u003e[] = \u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003et.group_ID = ?\u003c/span\u003e\u0026quot;\u003c/span\u003e;","    \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003eparams\u003c/span\u003e[] = \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003efilter_group\u003c/span\u003e;","}","","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ewhere_sql\u003c/span\u003e = \u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003eWHERE \u003c/span\u003e\u0026quot;\u003c/span\u003e . \u003cspan class=pl-en\u003eimplode\u003c/span\u003e(\u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003e AND \u003c/span\u003e\u0026quot;\u003c/span\u003e, \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ewhere\u003c/span\u003e);","","\u003cspan class=pl-c\u003e// 撈出狀態為 3（審核通過）的最新專題\u003c/span\u003e","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003estmt\u003c/span\u003e = \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003epdo\u003c/span\u003e-\u0026gt;\u003cspan class=pl-en\u003eprepare\u003c/span\u003e(\u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003e\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e    SELECT latest.projects_ID, t.team_project_name, t.team_year,\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e           g.group_name AS group_display, latest.projects_describe, latest.projects_img\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e    FROM (\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e        SELECT p1.*\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e        FROM projectsdata p1\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e        INNER JOIN (\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e            SELECT team_ID, MAX(projects_update_d) AS latest_time\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e            FROM projectsdata\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e            GROUP BY team_ID\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e        ) p2 ON p1.team_ID = p2.team_ID AND p1.projects_update_d = p2.latest_time\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e    ) latest\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e    JOIN teamdata t ON latest.team_ID = t.team_ID\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e    LEFT JOIN groupdata g ON t.group_ID = g.group_ID\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e    \u003c/span\u003e\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ewhere_sql\u003c/span\u003e\u003cspan class=pl-s\u003e\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e    ORDER BY t.team_year DESC, latest.projects_update_d DESC\u003c/span\u003e\u003c/span\u003e","\u003cspan class=pl-s\u003e\u003cspan class=pl-s\u003e\u003c/span\u003e\u0026quot;\u003c/span\u003e);","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003estmt\u003c/span\u003e-\u0026gt;\u003cspan class=pl-en\u003eexecute\u003c/span\u003e(\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003eparams\u003c/span\u003e);","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003eprojects\u003c/span\u003e = \u003cspan class=pl-s1\u003e\u0